import{createStudy,clamp,lerp,downloadSVG}from'./core.js';
const study=createStudy({id:19,title:'Light Matter',category:'Parallax / Illumination',accent:'#f4b85d',background:'#112b34',foreground:'#eef2e6'}),svg=document.querySelector('#light-art'),group=document.querySelector('#paper-layers'),stage=document.querySelector('.light-world'),depth=document.querySelector('#paper-depth'),warm=document.querySelector('#paper-light');
const colors=['#102b36','#194552','#2b6070','#448690','#83aaa0','#b8bea0','#dfc391'];const NS='http://www.w3.org/2000/svg';let pointer={x:0,y:0,tx:0,ty:0},scroll=0,offset=0,dirty=true,lastX=9,lastY=9,lastScroll=9;
for(let i=0;i<colors.length;i++){const p=document.createElementNS(NS,'path');const rx=530-i*51,ry=395-i*34,cx=665+i*8,cy=430-i*10;let hole='';for(let j=0;j<=100;j++){const t=j/100*Math.PI*2,r=1+Math.sin(t*3+i*.6)*.05+Math.cos(t*5-i*.7)*.025;const x=cx+Math.cos(t)*rx*r,y=cy+Math.sin(t)*ry*r;hole+=`${j?'L':'M'}${x.toFixed(2)} ${y.toFixed(2)} `}p.setAttribute('d','M-120 -120 H1320 V970 H-120 Z '+hole+'Z');p.setAttribute('fill-rule','evenodd');p.setAttribute('fill',colors[i]);p.setAttribute('filter','url(#paper-shadow)');group.prepend(p)}
function draw({dt}){const k=dt?1-Math.exp(-dt*6):study.running()?0:1;pointer.x=lerp(pointer.x,pointer.tx,k);pointer.y=lerp(pointer.y,pointer.ty,k);offset=lerp(offset,scroll,k);if(!dirty&&Math.abs(pointer.x-lastX)+Math.abs(pointer.y-lastY)+Math.abs(offset-lastScroll)<.0005)return;dirty=false;lastX=pointer.x;lastY=pointer.y;lastScroll=offset;const strength=+depth.value/100;for(let i=0;i<group.children.length;i++){const z=(7-i)/7,tx=pointer.x*z*28*strength,ty=pointer.y*z*20*strength,scale=1+offset*z*.24;group.children[i].setAttribute('transform',`translate(${tx.toFixed(2)} ${ty.toFixed(2)}) translate(665 430) scale(${scale.toFixed(4)}) translate(-665 -430)`)}document.querySelector('#light-sun').setAttribute('cx',(650+pointer.x*42).toFixed(2));document.querySelector('#light-sun').setAttribute('cy',(340+pointer.y*30-offset*70).toFixed(2));document.querySelector('#light-depth').textContent='DEPTH / '+depth.value+'%';svg.style.filter=`saturate(${.5+(+warm.value/100)*.8})`}
stage.addEventListener('pointermove',e=>{const r=stage.getBoundingClientRect();pointer.tx=(e.clientX-r.left)/r.width*2-1;pointer.ty=(e.clientY-r.top)/r.height*2-1;if(!study.running())return;study.invalidate()});stage.addEventListener('pointerleave',()=>{pointer.tx=pointer.ty=0;study.invalidate()});function measure(){if(study.running())scroll=clamp((72-document.querySelector('.light-scroll').getBoundingClientRect().top)/Math.max(1,document.querySelector('.light-scroll').offsetHeight-stage.offsetHeight));study.invalidate()}window.addEventListener('scroll',measure,{passive:true});for(const input of[depth,warm])input.addEventListener('input',()=>{dirty=true;study.invalidate()});document.querySelector('#light-shift').addEventListener('click',()=>{pointer.tx=Math.sin((pointer.tx+1)*3.4);pointer.ty=Math.cos((pointer.ty+1)*2.7);dirty=true;study.invalidate()});study.onFrame(draw);study.onMotion(run=>{if(run)measure()});study.onResize(()=>{dirty=true;measure()});study.setReset(()=>{pointer={x:0,y:0,tx:0,ty:0};depth.value=50;warm.value=70;scroll=offset=0;dirty=true;window.scrollTo({top:0,behavior:'auto'})});study.setExport(()=>downloadSVG(svg,'sub-light-matter.svg'));study.cleanup(()=>window.removeEventListener('scroll',measure));
